SELECT ok((SELECT context_changed FROM public.get_work_order_lifecycle_context(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21))),'old status remains explicitly tied to its prior basis');
SELECT throws_ok($$SELECT public.mutate_work_order_lifecycle(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),1,(SELECT request_values FROM public.work_order_lifecycle_versions WHERE version=1),pg_temp.k(202))$$,'PT409',NULL,'old open context cannot silently adopt the new plan');
SELECT lives_ok($$SELECT pg_temp.change(31,1,202,'transition','planned')$$,'valid plan can be planned while its date is unknown');
SELECT ok((SELECT (basis->>'unknownPlannedDate')::boolean FROM public.get_work_order_lifecycle_context(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21))),'unknown planned date remains visible');
