SELECT set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
SELECT lives_ok($$SELECT pg_temp.execution(0,301,NULL,'unknown')$$,'actual factual record may retain missing method and coverage');
SELECT throws_ok($$SELECT pg_temp.change(31,6,207,'transition','performed')$$,'22023',NULL,'performed status requires actual method and coverage');
SELECT lives_ok($$SELECT pg_temp.execution(1,302,'Synthetic actual method','unknown')$$,'method correction preserves first actual revision');
SELECT throws_ok($$SELECT pg_temp.change(31,6,207,'transition','performed')$$,'22023',NULL,'unknown coverage is not measured completion');
