SET CONSTRAINTS work_order_execution_required IMMEDIATE;
SET CONSTRAINTS work_order_execution_required DEFERRED;
SELECT lives_ok($$SELECT pg_temp.change(31,6,207,'transition','performed')$$,'performed fact can be confirmed while attachment gaps remain');
SELECT ok((SELECT (basis->'documentationGaps') ? 'deviation_attachment_missing' FROM public.get_work_order_lifecycle_context(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21))),'missing deviation attachment remains an explicit documentation gap');
SELECT throws_ok($$SELECT pg_temp.change(31,7,208,'transition','submitted')$$,'22023',NULL,'ordinary API cannot submit without frozen evidence/checklist requirements');
SELECT throws_ok($$INSERT INTO public.work_order_lifecycle_versions(action_id,organization_id,project_id,version,status,request_values,request_id) VALUES(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),8,'approved',pg_temp.values_for(31,'transition','approved'),pg_temp.k(208))$$,'22023',NULL,'direct table API cannot bypass approval workflow');
SELECT is((SELECT status FROM public.actions WHERE id=pg_temp.k(31)),'planned','legacy planning/commercial status is not silently overwritten');
INSERT INTO pg_temp.refs SELECT 'frozen_plan',plan_version_id FROM public.work_order_lifecycle_versions WHERE action_id=pg_temp.k(31) AND version=7;
