SELECT lives_ok($$SELECT public.save_work_order_plan(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),2,pg_temp.plan(),'Synthetic later plan correction',pg_temp.k(103))$$,'later plan change never rewrites performed history');
