SELECT throws_ok($$SELECT pg_temp.note(501,2,603,'Moved note','Synthetic correction',(SELECT id FROM public.work_order_plan_versions WHERE action_id=pg_temp.k(31) ORDER BY version DESC LIMIT 1))$$,'23503',NULL,'a correction cannot move its historical context');
SELECT is((SELECT array_agg(version) FROM public.get_work_order_note_history(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),pg_temp.k(501),NULL,1)),ARRAY[2,1],'note history has stable descending lookahead');
SELECT throws_ok($$INSERT INTO public.audit_events(project_id,event_type,entity_type,entity_id,title,actor,source,after_data) VALUES(pg_temp.k(21),'work_order.lifecycle_changed','work_order',pg_temp.k(31),'Forged approved',pg_temp.k(1)::text,'database_trigger','{}')$$,'42501',NULL,'manual event cannot impersonate server approval/status');
SELECT lives_ok($$SELECT public.save_work_order_access(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),pg_temp.k(3),0,true,true,false,'Synthetic external task delegate',pg_temp.k(701))$$,'external collaborator receives only concrete task capability');
