-- Simulate isolated audit corruption as database owner; the canonical note remains visible.
RESET ROLE;
DELETE FROM public.audit_events WHERE event_type='work_order.note_saved' AND after_data->>'requestId'=pg_temp.k(606)::text;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
SELECT ok((SELECT NOT (item->>'audit_recorded')::boolean FROM public.get_work_order_log(pg_temp.k(31),pg_temp.k(11),pg_temp.k(21),NULL,NULL,NULL,50)l CROSS JOIN LATERAL jsonb_array_elements(l.log->'items')item WHERE item->'detail'->>'body'='Synthetic note after snapshot'),'missing audit proof is explicit rather than hiding the original note');
RESET ROLE;
CREATE FUNCTION pg_temp.fail_lifecycle_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic lifecycle audit failure' USING ERRCODE='P0001';END $$;
CREATE TRIGGER synthetic_lifecycle_audit_failure BEFORE INSERT ON public.audit_events FOR EACH ROW WHEN(NEW.event_type='work_order.lifecycle_changed') EXECUTE FUNCTION pg_temp.fail_lifecycle_audit();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
SELECT throws_ok($$SELECT pg_temp.change(31,8,209,'confirm','performed','{"reason":"Synthetic same basis checked"}')$$,'P0001',NULL,'audit failure rejects entire status mutation');
SELECT is((SELECT max(version) FROM public.work_order_lifecycle_versions WHERE action_id=pg_temp.k(31)),8,'failed audit leaves no partial status');
RESET ROLE;
DROP TRIGGER synthetic_lifecycle_audit_failure ON public.audit_events;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
SELECT lives_ok($$SELECT pg_temp.change(31,8,209,'confirm','performed','{"reason":"Synthetic same basis checked"}')$$,'same mutation can retry after full transaction rollback');
SELECT * FROM finish();
ROLLBACK;
